sealed class SdkFfiException(message: String): kotlin.Exception(message) {
        
        class Generic(message: String) : SdkFfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SdkFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): SdkFfiException = FfiConverterTypeSdkFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeSdkFfiError : FfiConverterRustBuffer<SdkFfiException> {
    override fun read(buf: ByteBuffer): SdkFfiException {
        
            return when(buf.getInt()) {
            1 -> SdkFfiException.Generic(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: SdkFfiException): ULong {
        return 4UL
    }

    override fun write(value: SdkFfiException, buf: ByteBuffer) {
        when(value) {
            is SdkFfiException.Generic -> {
                buf.putInt(1)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




